WHERE term_condition_applies.is_active = 1

    AND term_condition_applies.module_type_id = #{filter.moduleTypeId}


  AND module_types.name LIKE CONCAT("%", #{filter.searchText}, "%")

mapper.select:
SELECT




GROUP BY term_condition_applies.term_condition_type_id

ORDER BY


       ${filter.orderBy}


         term_condition_applies.id DESC


LIMIT #{filter.page}, #{filter.rowsPerPage}
